  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Como as linguagens combinadas produzem sentidos', 'Um texto multissemiótico combina modos. Analise cada escolha, a relação entre elas e o contexto; sustente a interpretação com evidências sem atribuir um efeito universal ou um resultado que o texto não comprova.', '## 1. Descreva antes de interpretar
Identifique o que está presente: palavras, imagem, som, gesto, movimento, posição, escala ou sequência. Registre observações concretas, como “o título está no topo” ou “a música fica mais lenta”, antes de concluir o que significam. Descrição e interpretação são passos relacionados, mas não iguais.

## 2. Pergunte o que cada modo permite destacar
Palavras podem nomear, explicar uma condição ou organizar uma sequência; uma imagem pode mostrar relações espaciais; som e ritmo podem marcar transições; gesto e enquadramento podem direcionar atenção. Essas são possibilidades, não regras universais. Considere o gênero, o público, o propósito e a cultura de circulação.

## 3. Analise a relação entre os modos
Uma legenda pode complementar uma imagem, restringir sua leitura, entrar em contraste com ela ou repetir a mesma informação. Uma trilha pode acompanhar uma cena ou criar tensão em relação a ela. Observe também hierarquia visual, proximidade, tamanho e ordem: o elemento mais saliente tende a chamar atenção, mas isso não prova o que cada pessoa percebeu.

## 4. Sustente e limite a interpretação
Use a estrutura “o elemento X pode produzir o efeito Y neste contexto porque…”. Aponte a evidência específica e considere uma leitura alternativa. Para afirmar que uma campanha mudou comportamento, por exemplo, é preciso medir comportamento; a análise da mensagem, sozinha, só permite discutir estratégias e efeitos possíveis.

## Exemplo resolvido
Um aviso autoral traz “A biblioteca fecha às 18h” em letras pequenas, enquanto “DEVOLVA HOJE” aparece em letras grandes ao lado de um ícone de relógio. A hierarquia torna a ação imediata mais saliente. Isso apoia a leitura de que o aviso prioriza a devolução no mesmo dia, mas não prova que alguém devolveu o livro nem que todas as pessoas perceberam o aviso. Uma leitura alternativa pode considerar que o ícone apenas organiza o tema; para comparar, observamos posição, tamanho, texto e contexto de circulação.

## Roteiro de análise
1. Descreva os modos e os elementos observáveis. 2. Relacione duas escolhas e explique o efeito possível. 3. Considere público, gênero e circulação. 4. Cite a evidência e indique o limite do que ela permite afirmar.',
    'Em um infográfico autoral, o título diz “Uso de bicicletas no bairro”, as barras comparam três meses e uma legenda associa cada cor a uma região. A legenda permite identificar as séries; a escala permite comparar valores. Esses elementos apoiam uma interpretação da variação mostrada, mas não demonstram por que ela ocorreu nem se todos os moradores pedalam mais.', array['Separe o que você observa do que interpreta.', 'Relacione pelo menos dois modos e cite o elemento concreto que sustenta sua leitura.', 'Use “pode sugerir” quando o efeito depender de público ou contexto.', 'Não transforme uma mensagem em prova de comportamento ou resultado.']::text[], 24, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-languages-semiotic-function","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Identificar título, legenda, imagem e informação principal em um texto.","Distinguir uma observação de uma conclusão ou opinião."],"key_concepts":["Modo semiótico é um recurso de produção de sentido, como linguagem verbal, imagem, som, gesto e organização espacial.","A relação entre modos pode complementar, repetir, restringir ou tensionar sentidos.","Salência organiza a atenção, mas não prova intenção nem recepção universal.","Uma interpretação crítica vincula evidência observável, contexto e efeito possível.","A análise da mensagem não substitui dados necessários para comprovar impacto fora do texto."],"progression":[{"stage":"FOUNDATION","focus":"Descrever modos e reconhecer a contribuição de cada elemento.","questionIds":["v5-lgg103-probe-01","v5-lgg103-probe-02","v5-lgg103-practice-01"]},{"stage":"APPLICATION","focus":"Relacionar escolhas verbais e não verbais com evidências do texto.","questionIds":["v5-lgg103-practice-03","v5-lgg103-practice-07","v5-lgg103-practice-10"]},{"stage":"TRANSFER","focus":"Analisar a relação entre modos em gêneros e situações diferentes.","questionIds":["v5-lgg103-transfer-01","v5-lgg103-transfer-04","v5-lgg103-transfer-07"]},{"stage":"INTEGRATION","focus":"Avaliar interpretações alternativas e limites das conclusões.","questionIds":["v5-lgg103-lock-01","v5-lgg103-lock-04","v5-lgg103-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar o roteiro em novos gêneros; o agendamento espaçado depende de mecanismo separado.","questionIds":["v5-lgg103-review-02","v5-lgg103-review-06","v5-lgg103-review-09"]}],"micro_explanations":[{"trigger":"DESCRIPTION_AS_INTERPRETATION","text":"Primeiro escreva o que está visível ou audível; depois diga que leitura isso permite. Assim fica claro qual evidência sustenta a interpretação."},{"trigger":"MESSAGE_AS_PROOF_OF_IMPACT","text":"Um texto pode tentar persuadir. Para afirmar que mudou uma atitude, é preciso medir a atitude com método e contexto descritos."},{"trigger":"UNIVERSAL_RECEPTION","text":"Prefira “pode sugerir” e indique a pista e o contexto; leitores diferentes podem responder de modos distintos."}],"remediations":[{"misconception":"LIST_MODES_WITHOUT_RELATION","prompt":"Escolha duas modalidades presentes e complete: “A escolha X complementa/contrasta com Y porque...”. Cite detalhes observáveis."},{"misconception":"INTENTION_OR_EFFECT_WITHOUT_EVIDENCE","prompt":"Sublinhe a evidência que apoia sua leitura. Reescreva afirmações sobre intenção ou público como possibilidades, a menos que haja dados diretos."},{"misconception":"MESSAGE_AS_MEASURED_RESULT","prompt":"Separe em duas colunas: o que o texto faz e o que aconteceu fora dele. Indique que dado seria necessário para demonstrar o resultado externo."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Linguagens e suas Tecnologias no Ensino Médio","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["EM13LGG103 identifies verbal, visual, sound and gestural semioses","the area describes hybrid combinations in multisemiotic texts"],"use":"Reference for content scope only. The internal skill remains a candidate; this package does not claim an officially approved mapping."},{"title":"Developing a systemic functional approach to teach multimodal literacy","publisher":"Functional Linguistics / Springer Nature","url":"https://link.springer.com/article/10.1186/s40554-018-0066-8","accessedOn":"2026-10-13","supports":["explicitly naming textual features and relating modes","supporting interpretations with textual evidence","treating mode affordances as contextual rather than universal"],"use":"Methodological reference for original scaffolds and evidence-oriented feedback; no text or item copied."}],"copyright_note":"All scenarios, questions, options, explanations, hints and remediations in this pack are original. Sources support scope and instructional design only. No official mapping approval or human pedagogical review is claimed.","objective":"Analisar como escolhas verbais, visuais, sonoras, espaciais ou gestuais contribuem para a interpretação de um texto e justificar leituras com elementos observáveis, distinguindo efeitos possíveis de resultados comprovados.","common_mistake":"Afirmar intenção, emoção universal ou impacto real só porque um recurso visual ou sonoro parece persuasivo.","estimated_minutes":24}'::jsonb
