  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-lgg103-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"SCHOOL_NOTICE_HIERARCHY","statement":"Em um aviso, “DEVOLVA HOJE” aparece em letras grandes e a data de fechamento em letras menores. Qual descrição é sustentada pela composição?","options":["A hierarquia visual destaca a ação de devolver hoje.","O aviso prova que todos devolverão o livro.","O tamanho das letras revela a opinião de cada leitor.","A data deixa de fazer parte do texto."],"correctAnswer":"A hierarquia visual destaca a ação de devolver hoje.","explanation":"O tamanho relativo torna uma informação mais saliente, mas não demonstra a reação de todos os leitores.","hint":"Compare o que a composição torna mais saliente com o que ela não mede.","errorFocus":"Tratar saliência como prova de comportamento","misconceptions":{"O aviso prova que todos devolverão o livro.":["SALience_AS_BEHAVIOR"],"O tamanho das letras revela a opinião de cada leitor.":["DESIGN_AS_RECEPTION_DATA"],"A data deixa de fazer parte do texto.":["SMALL_TEXT_AS_ABSENT"]},"position":1},{"id":"v5-lgg103-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"MAP_LEGEND","statement":"Um mapa escolar usa azul para rios e verde para parques; a legenda associa cada cor a uma categoria. Para que ela serve principalmente?","options":["Provar que o mapa foi medido com precisão.","Ajudar a identificar o que cada cor representa.","Mostrar que todas as pessoas preferem parques.","Substituir a escala e a orientação do mapa."],"correctAnswer":"Ajudar a identificar o que cada cor representa.","explanation":"A legenda permite interpretar símbolos e cores; não certifica a qualidade dos dados nem substitui outros elementos cartográficos.","hint":"Pergunte qual dúvida a legenda resolve para quem lê o mapa.","errorFocus":"Atribuir à legenda funções de validação ou escala","misconceptions":{"Provar que o mapa foi medido com precisão.":["LEGEND_AS_VALIDATION"],"Mostrar que todas as pessoas preferem parques.":["MAP_AS_PREFERENCE_SURVEY"],"Substituir a escala e a orientação do mapa.":["LEGEND_AS_ALL_MAP_ELEMENTS"]},"position":2},{"id":"v5-lgg103-probe-03","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"PODCAST_PAUSE","statement":"Em um podcast ficcional, a fala para por alguns segundos antes da notícia principal, enquanto um som breve continua. O que essa pausa permite analisar?","options":["A pausa prova que o público ficou ansioso.","O som informa quantos ouvintes escutaram.","A combinação pode criar expectativa dentro do episódio.","O silêncio elimina a função da fala anterior."],"correctAnswer":"A combinação pode criar expectativa dentro do episódio.","explanation":"Ritmo e som podem criar expectativa como efeito possível; só a composição não mede o estado emocional da audiência.","hint":"Analise o efeito possível no próprio texto sonoro, não uma reação externa não medida.","errorFocus":"Inferir reação universal a partir de um recurso sonoro","misconceptions":{"A pausa prova que o público ficou ansioso.":["SOUND_AS_AUDIENCE_MEASURE"],"O som informa quantos ouvintes escutaram.":["AUDIO_AS_AUDIENCE_DATA"],"O silêncio elimina a função da fala anterior.":["PAUSE_AS_ERASURE"]},"position":3},{"id":"v5-lgg103-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"INFOGRAPHIC_CATEGORIES","statement":"Um infográfico apresenta barras de três bairros e uma legenda que associa cada cor a um bairro. Qual leitura é mais adequada?","options":["A legenda garante que os dados foram coletados sem erro.","A cor mais escura prova maior população.","O título explica sozinho todos os valores.","A legenda identifica a categoria representada por cada cor."],"correctAnswer":"A legenda identifica a categoria representada por cada cor.","explanation":"A legenda associa marcas visuais a categorias; a validade dos dados depende do método e da fonte.","hint":"Diferencie a chave de leitura do gráfico da qualidade da pesquisa.","errorFocus":"Confundir convenção gráfica com validação dos dados","misconceptions":{"A legenda garante que os dados foram coletados sem erro.":["LEGEND_AS_DATA_VALIDATION"],"A cor mais escura prova maior população.":["COLOR_AS_MAGNITUDE_WITHOUT_KEY"],"O título explica sozinho todos os valores.":["TITLE_AS_COMPLETE_DATA"]},"position":1},{"id":"v5-lgg103-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"POSTER_IMAGE_TEXT","statement":"Um cartaz traz a frase “leve sua garrafa” e mostra uma pessoa enchendo uma garrafa em um bebedouro. Qual relação entre os modos é mais plausível?","options":["A imagem exemplifica visualmente a recomendação verbal.","A imagem comprova que o cartaz reduziu o uso de copos.","A frase indica o material de que o bebedouro é feito.","A figura elimina a necessidade de considerar o texto."],"correctAnswer":"A imagem exemplifica visualmente a recomendação verbal.","explanation":"A imagem pode concretizar a recomendação; para demonstrar redução de copos, seria preciso medir esse resultado.","hint":"Qual função a cena cumpre em relação à frase, e qual resultado externo ela não comprova?","errorFocus":"Confundir exemplo visual com impacto comprovado","misconceptions":{"A imagem comprova que o cartaz reduziu o uso de copos.":["ILLUSTRATION_AS_IMPACT_DATA"],"A frase indica o material de que o bebedouro é feito.":["TEXT_SCOPE_MISREAD"],"A figura elimina a necessidade de considerar o texto.":["IMAGE_REPLACES_ALL_MODES"]},"position":2},{"id":"v5-lgg103-practice-03","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"CAPTION_SCOPE","statement":"Um vídeo de uma entrevista tem legendas que transcrevem a fala e indicam “[porta bate]”. O que essas legendas acrescentam?","options":["Identificam automaticamente quem está certo no debate.","Representam fala e um som relevante que ocorre na cena.","Mostram a reação emocional de cada pessoa que assiste.","Substituem qualquer informação visual do vídeo."],"correctAnswer":"Representam fala e um som relevante que ocorre na cena.","explanation":"Legendas podem tornar fala e sons relevantes acessíveis, mas não substituem todos os elementos visuais nem avaliam argumentos.","hint":"Observe quais informações sonoras foram convertidas em texto.","errorFocus":"Tratar legenda como interpretação total do vídeo","misconceptions":{"Identificam automaticamente quem está certo no debate.":["CAPTION_AS_TRUTH_JUDGMENT"],"Mostram a reação emocional de cada pessoa que assiste.":["CAPTION_AS_VIEWER_RESPONSE"],"Substituem qualquer informação visual do vídeo.":["CAPTION_AS_FULL_VISUAL_DESCRIPTION"]},"position":3},{"id":"v5-lgg103-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"ALT_TEXT_RELEVANCE","statement":"Uma imagem de um gráfico será usada em uma página com leitor de tela. Qual alternativa descreve uma boa decisão de texto alternativo?","options":["Escrever “imagem bonita” para todos os gráficos.","Repetir o nome do arquivo sem explicar a figura.","Informar o tema e os dados ou relações essenciais mostrados.","Adivinhar a intenção de quem produziu o gráfico."],"correctAnswer":"Informar o tema e os dados ou relações essenciais mostrados.","explanation":"Um texto alternativo útil comunica a informação relevante da imagem para aquela finalidade, sem inventar intenção.","hint":"Pense no que uma pessoa precisa saber para compreender a função do gráfico na página.","errorFocus":"Descrição genérica ou inferência de intenção em alternativa textual","misconceptions":{"Escrever “imagem bonita” para todos os gráficos.":["ALT_TEXT_GENERIC"],"Repetir o nome do arquivo sem explicar a figura.":["FILENAME_AS_DESCRIPTION"],"Adivinhar a intenção de quem produziu o gráfico.":["ALT_TEXT_AS_AUTHOR_MINDREADING"]},"position":4},{"id":"v5-lgg103-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"CHART_SCALE","statement":"Um gráfico de barras começa o eixo vertical em 98 e mostra valores 99 e 100 com barras de alturas muito diferentes. O que a análise deve considerar?","options":["A diferença visual é sempre proporcional ao valor total.","A barra maior prova que a categoria é melhor.","A cor das barras confirma que a amostra é representativa.","O início do eixo pode ampliar a diferença percebida; confira escala e valores."],"correctAnswer":"O início do eixo pode ampliar a diferença percebida; confira escala e valores.","explanation":"Uma escala truncada pode exagerar visualmente diferenças pequenas; a leitura precisa observar eixo, valores e contexto.","hint":"Compare o tamanho aparente das barras com os números e o ponto inicial do eixo.","errorFocus":"Ler magnitude gráfica sem verificar a escala","misconceptions":{"A diferença visual é sempre proporcional ao valor total.":["VISUAL_LENGTH_AS_RAW_VALUE"],"A barra maior prova que a categoria é melhor.":["MAGNITUDE_AS_VALUE_JUDGMENT"],"A cor das barras confirma que a amostra é representativa.":["COLOR_AS_SAMPLING_METHOD"]},"position":5},{"id":"v5-lgg103-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"CONTRAST_ACCESSIBILITY","statement":"Em uma página, texto cinza-claro aparece sobre fundo branco e um aviso importante é indicado apenas pela cor vermelha. Que problema de projeto pode ser apontado?","options":["Baixo contraste e dependência só da cor podem dificultar acesso à informação.","O projeto prova que leitores não compreenderam a página.","A cor vermelha sempre significa perigo em qualquer contexto.","O fundo branco impede que qualquer cor tenha significado."],"correctAnswer":"Baixo contraste e dependência só da cor podem dificultar acesso à informação.","explanation":"Contraste e redundância de sinais podem afetar legibilidade e acessibilidade; não sabemos a compreensão real sem avaliação com usuários.","hint":"Descreva uma barreira observável e separe-a de uma afirmação sobre todos os leitores.","errorFocus":"Transformar risco de acessibilidade em dado de compreensão universal","misconceptions":{"O projeto prova que leitores não compreenderam a página.":["DESIGN_RISK_AS_USER_STUDY"],"A cor vermelha sempre significa perigo em qualquer contexto.":["COLOR_MEANING_UNIVERSAL"],"O fundo branco impede que qualquer cor tenha significado.":["BACKGROUND_AS_MEANING_ERASURE"]},"position":6},{"id":"v5-lgg103-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"COMIC_PANEL_SEQUENCE","statement":"Em uma tira autoral, três quadros mostram uma pessoa olhando para o céu, depois um guarda-chuva fechado e, por fim, gotas na janela. Como a sequência contribui para o sentido?","options":["O último quadro prova que a pessoa já sabia a previsão.","A ordem dos quadros permite inferir uma pequena sequência narrativa.","O guarda-chuva informa a temperatura exata.","A sequência elimina qualquer possibilidade de humor."],"correctAnswer":"A ordem dos quadros permite inferir uma pequena sequência narrativa.","explanation":"A disposição temporal dos quadros convida o leitor a relacionar acontecimentos; não revela conhecimento ou intenção não mostrados.","hint":"Observe o que muda de um quadro para o seguinte.","errorFocus":"Inferir conhecimento ou causa além da sequência observada","misconceptions":{"O último quadro prova que a pessoa já sabia a previsão.":["SEQUENCE_AS_PRIOR_KNOWLEDGE"],"O guarda-chuva informa a temperatura exata.":["OBJECT_AS_MEASUREMENT"],"A sequência elimina qualquer possibilidade de humor.":["NARRATIVE_AS_SINGLE_EFFECT"]},"position":7},{"id":"v5-lgg103-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"SOUNDTRACK_CONTRAST","statement":"Uma cena mostra uma praça vazia ao amanhecer, mas a trilha sonora tem ritmo acelerado. Qual análise respeita os dois modos?","options":["A música prova que a praça foi filmada à noite.","A imagem deixa de informar qualquer coisa sobre o espaço.","O contraste pode criar tensão ou movimento, conforme o conjunto da cena.","Todos os espectadores sentirão a mesma emoção."],"correctAnswer":"O contraste pode criar tensão ou movimento, conforme o conjunto da cena.","explanation":"A trilha pode tensionar ou alterar a leitura da imagem, mas o efeito depende da composição e do público.","hint":"Compare o que a imagem mostra com o ritmo da trilha; evite universalizar a reação.","errorFocus":"Usar a trilha como evidência factual da imagem ou da reação do público","misconceptions":{"A música prova que a praça foi filmada à noite.":["SOUND_AS_SCENE_FACT"],"A imagem deixa de informar qualquer coisa sobre o espaço.":["MODE_CONTRAST_AS_ERASURE"],"Todos os espectadores sentirão a mesma emoção.":["UNIVERSAL_AFFECT"]},"position":8},{"id":"v5-lgg103-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"PHOTO_CAPTION_TENSION","statement":"Uma foto mostra uma rua com poucas pessoas, mas a legenda diz “centro lotado no sábado”. Qual procedimento é mais crítico?","options":["Tomar a legenda como verdade por estar junto à foto.","Concluir que a foto foi manipulada sem verificar origem.","Ignorar a imagem e repetir apenas a legenda.","Comparar data, local, enquadramento e outras informações antes de decidir."],"correctAnswer":"Comparar data, local, enquadramento e outras informações antes de decidir.","explanation":"Imagem e legenda podem estar em tensão; origem, recorte e contexto ajudam a avaliar a afirmação sem concluir fraude automaticamente.","hint":"Que informações externas ajudariam a verificar se imagem e legenda tratam da mesma situação?","errorFocus":"Aceitar ou rejeitar uma legenda sem verificar contexto","misconceptions":{"Tomar a legenda como verdade por estar junto à foto.":["CAPTION_AUTHORITY"],"Concluir que a foto foi manipulada sem verificar origem.":["DISAGREEMENT_AS_FRAUD"],"Ignorar a imagem e repetir apenas a legenda.":["TEXT_ONLY_CONFIRMATION"]},"position":9},{"id":"v5-lgg103-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"EMOJI_CONTEXT","statement":"Em uma mensagem de equipe, uma pessoa responde “ótimo 🙃” depois que uma tarefa é refeita pela terceira vez. O que a análise do emoji deve considerar?","options":["O contexto e a relação com a frase podem produzir ironia, mas a leitura não é certa sem mais pistas.","O emoji tem um sentido fixo e igual em toda conversa.","O emoji prova que a pessoa está feliz.","A frase deixa de ter qualquer papel na interpretação."],"correctAnswer":"O contexto e a relação com a frase podem produzir ironia, mas a leitura não é certa sem mais pistas.","explanation":"O emoji pode alterar ou tensionar a frase; contexto ajuda, mas não garante a intenção de quem escreveu.","hint":"Relacione a palavra, o símbolo e a situação descrita; formule a interpretação como possibilidade.","errorFocus":"Atribuir significado universal ou intenção certa a um emoji","misconceptions":{"O emoji tem um sentido fixo e igual em toda conversa.":["EMOJI_UNIVERSAL"],"O emoji prova que a pessoa está feliz.":["ICON_AS_INTENTION_PROOF"],"A frase deixa de ter qualquer papel na interpretação.":["EMOJI_REPLACES_LANGUAGE"]},"position":10},{"id":"v5-lgg103-practice-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"PUBLIC_SERVICE_LAYOUT","statement":"Um folheto de saúde coloca o telefone de atendimento em um rodapé pequeno, enquanto a ilustração ocupa quase toda a página. Qual crítica é mais bem apoiada?","options":["A ilustração prova que o serviço não funciona.","A hierarquia pode tornar o contato menos saliente que a imagem.","O rodapé não faz parte do folheto.","Toda pessoa deixará de encontrar o telefone."],"correctAnswer":"A hierarquia pode tornar o contato menos saliente que a imagem.","explanation":"Posição e tamanho podem orientar a atenção e são uma base concreta para crítica; para saber se o telefone foi encontrado, seria preciso observar leitores.","hint":"Descreva a posição relativa; não afirme a reação de todas as pessoas.","errorFocus":"Confundir uma escolha de hierarquia com resultado medido","misconceptions":{"A ilustração prova que o serviço não funciona.":["DESIGN_AS_SERVICE_OUTCOME"],"O rodapé não faz parte do folheto.":["LOW_SALIENCE_AS_ABSENCE"],"Toda pessoa deixará de encontrar o telefone.":["UNIVERSAL_USER_FAILURE"]},"position":11},{"id":"v5-lgg103-practice-12","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CHART_TITLE_SCOPE","statement":"Um gráfico tem o título “A cidade prefere ônibus”, mas apresenta apenas respostas de 30 passageiros em um terminal. Qual avaliação é mais cuidadosa?","options":["O título é provado por qualquer grupo de respostas.","O gráfico não pode informar nada sobre os participantes entrevistados.","A amostra descrita não basta, por si só, para generalizar a preferência de toda a cidade.","A imagem do gráfico substitui os dados da pesquisa."],"correctAnswer":"A amostra descrita não basta, por si só, para generalizar a preferência de toda a cidade.","explanation":"O título amplia a conclusão além da amostra indicada; o gráfico ainda pode descrever as respostas do grupo, com limites explícitos.","hint":"Compare o alcance do título com quem foi efetivamente ouvido.","errorFocus":"Generalizar de uma amostra localizada para toda a cidade","misconceptions":{"O título é provado por qualquer grupo de respostas.":["TITLE_AS_EVIDENCE"],"O gráfico não pode informar nada sobre os participantes entrevistados.":["LIMITATION_AS_TOTAL_INVALIDITY"],"A imagem do gráfico substitui os dados da pesquisa.":["VISUAL_AS_METHOD"]},"position":12},{"id":"v5-lgg103-practice-13","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"INSTRUCTIONAL_DIAGRAM","statement":"Um manual mostra quatro setas numeradas ao lado de um parágrafo com instruções. Por que os dois recursos podem funcionar em conjunto?","options":["As setas provam que qualquer pessoa concluirá a tarefa.","O parágrafo torna desnecessária a numeração.","A numeração informa o tempo exato de execução.","As setas organizam visualmente a ordem, enquanto o texto pode explicar condições de cada passo."],"correctAnswer":"As setas organizam visualmente a ordem, enquanto o texto pode explicar condições de cada passo.","explanation":"A sequência visual e a explicação verbal podem dividir funções; a composição não garante sucesso ou duração universal.","hint":"Identifique uma contribuição de cada recurso e o que nenhum deles mede sozinho.","errorFocus":"Confundir organização de instruções com garantia de resultado","misconceptions":{"As setas provam que qualquer pessoa concluirá a tarefa.":["INSTRUCTION_AS_SUCCESS_GUARANTEE"],"O parágrafo torna desnecessária a numeração.":["TEXT_IMAGE_REDUNDANCY_ASSUMPTION"],"A numeração informa o tempo exato de execução.":["ORDER_AS_DURATION"]},"position":13},{"id":"v5-lgg103-practice-14","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"MEME_REFRAMING","statement":"Um meme combina a foto de uma fila com a frase “rapidinho, disseram”. Que aspecto da relação texto-imagem sustenta uma leitura humorística?","options":["A combinação pode contrastar a promessa de rapidez com a fila mostrada.","A foto prova quem falou a frase.","O texto precisa descrever literalmente cada pessoa da fila.","A imagem tem um significado humorístico universal."],"correctAnswer":"A combinação pode contrastar a promessa de rapidez com a fila mostrada.","explanation":"O humor plausível nasce do contraste entre fala e situação representada; a imagem não comprova a autoria da frase nem uma leitura universal.","hint":"Observe a diferença entre a expectativa verbal e a situação visual.","errorFocus":"Ignorar o contraste ou tratar interpretação humorística como universal","misconceptions":{"A foto prova quem falou a frase.":["IMAGE_AS_QUOTE_PROVENANCE"],"O texto precisa descrever literalmente cada pessoa da fila.":["TEXT_AS_LITERAL_CAPTION_ONLY"],"A imagem tem um significado humorístico universal.":["HUMOR_UNIVERSAL"]},"position":14},{"id":"v5-lgg103-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"EMERGENCY_AUDIO_VISUAL","statement":"Um vídeo de orientação mostra uma saída sinalizada e uma narração diz “use a rota indicada”. Qual conclusão considera a articulação dos modos sem exceder a evidência?","options":["A narração prova que a rota estará sempre desobstruída.","A narração e a sinalização podem se reforçar, mas a segurança da rota depende de condições verificadas no local.","A placa deixa a fala sem função possível.","Todos interpretarão a sinalização do mesmo modo."],"correctAnswer":"A narração e a sinalização podem se reforçar, mas a segurança da rota depende de condições verificadas no local.","explanation":"Imagem e fala podem reforçar uma instrução; a situação real da rota exige verificação independente.","hint":"Separe a coerência da orientação no vídeo da condição real do espaço.","errorFocus":"Tratar representação como garantia de condição externa","misconceptions":{"A narração prova que a rota estará sempre desobstruída.":["MEDIA_AS_LIVE_STATUS"],"A placa deixa a fala sem função possível.":["ONE_MODE_EXCLUDES_OTHER"],"Todos interpretarão a sinalização do mesmo modo.":["UNIVERSAL_COMPREHENSION"]},"position":1},{"id":"v5-lgg103-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"TWO_CAMPAIGN_VERSIONS","statement":"Duas versões de um convite usam o mesmo texto. A primeira mostra o endereço em destaque; a segunda destaca uma fotografia do local. Que comparação pode ser feita?","options":["A versão com foto necessariamente terá mais participantes.","As versões comunicam sentidos idênticos porque as palavras são iguais.","A saliência muda e pode priorizar informações diferentes para quem lê.","A fotografia prova que o evento ocorrerá naquele endereço."],"correctAnswer":"A saliência muda e pode priorizar informações diferentes para quem lê.","explanation":"A organização visual altera o que recebe destaque mesmo quando o texto verbal permanece; participação e veracidade do endereço exigem outras evidências.","hint":"Compare a hierarquia dos elementos, não resultados de público que não foram medidos.","errorFocus":"Reduzir sentido ao texto verbal ou prever audiência sem dados","misconceptions":{"A versão com foto necessariamente terá mais participantes.":["DESIGN_AS_ATTENDANCE_CAUSE"],"As versões comunicam sentidos idênticos porque as palavras são iguais.":["WORDS_ONLY_MEANING"],"A fotografia prova que o evento ocorrerá naquele endereço.":["IMAGE_AS_EVENT_VERIFICATION"]},"position":2},{"id":"v5-lgg103-transfer-03","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"JUSTIFY","contextFamily":"ACCESSIBLE_EVENT_MAP","statement":"Um mapa de um evento marca uma rota acessível com linha contínua e um texto informa que há elevador. O que a análise pode sustentar?","options":["A rota será acessível para toda pessoa em qualquer condição.","O texto prova que o elevador estará funcionando no dia.","A linha no mapa substitui a descrição de acesso.","Mapa e texto apresentam informações complementares, que ainda precisam ser verificadas na situação de uso."],"correctAnswer":"Mapa e texto apresentam informações complementares, que ainda precisam ser verificadas na situação de uso.","explanation":"Os modos podem orientar localização e informar um recurso, mas disponibilidade e adequação dependem de checagem atualizada.","hint":"Distinga o que os materiais anunciam de uma condição que pode mudar.","errorFocus":"Confundir informação publicada com disponibilidade garantida","misconceptions":{"A rota será acessível para toda pessoa em qualquer condição.":["UNIVERSAL_ACCESS_CLAIM"],"O texto prova que o elevador estará funcionando no dia.":["NOTICE_AS_REALTIME_STATUS"],"A linha no mapa substitui a descrição de acesso.":["MAP_AS_COMPLETE_ACCESS_DESCRIPTION"]},"position":3},{"id":"v5-lgg103-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SHORT_VIDEO_CUT","statement":"Um vídeo curto corta a fala de uma entrevistada logo depois de uma frase, mas exibe uma legenda resumindo sua posição. O que uma leitura crítica deve fazer?","options":["Comparar o trecho disponível com a fonte completa e tratar a legenda como uma seleção editorial.","Aceitar o resumo como transcrição completa.","Concluir que houve manipulação intencional só pelo corte.","Ignorar a edição porque o vídeo tem som."],"correctAnswer":"Comparar o trecho disponível com a fonte completa e tratar a legenda como uma seleção editorial.","explanation":"Edição e legenda selecionam informação; para avaliar fidelidade e intenção, é preciso confrontar a fonte completa e o contexto.","hint":"Identifique a seleção visível e qual fonte adicional permite verificar o que ficou fora.","errorFocus":"Tomar recorte como totalidade ou inferir intenção sem comparação","misconceptions":{"Aceitar o resumo como transcrição completa.":["CAPTION_AS_FULL_SOURCE"],"Concluir que houve manipulação intencional só pelo corte.":["EDIT_AS_INTENT_PROOF"],"Ignorar a edição porque o vídeo tem som.":["AUDIO_AS_EDITORIAL_NEUTRALITY"]},"position":4},{"id":"v5-lgg103-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"POSTER_LANGUAGE_VARIANTS","statement":"Um cartaz de uma campanha comunitária usa uma expressão regional na fala de uma personagem e uma explicação em registro formal na legenda. Qual análise é mais adequada?","options":["A fala regional é um erro que a legenda corrige.","A diferença de registros pode aproximar a voz da personagem e explicitar a informação, dependendo do público e do propósito.","O registro formal prova que a personagem não compreende a mensagem.","Um registro deve ser usado em todos os contextos para ser correto."],"correctAnswer":"A diferença de registros pode aproximar a voz da personagem e explicitar a informação, dependendo do público e do propósito.","explanation":"Registros podem cumprir funções distintas e precisam ser analisados em contexto; variedade linguística não é defeito por si só.","hint":"Observe quem fala, para quem, em qual gênero e com que propósito.","errorFocus":"Hierarquizar variedades sem analisar função e contexto","misconceptions":{"A fala regional é um erro que a legenda corrige.":["DIALECT_AS_DEFICIENCY"],"O registro formal prova que a personagem não compreende a mensagem.":["REGISTER_AS_INTELLIGENCE"],"Um registro deve ser usado em todos os contextos para ser correto.":["ONE_REGISTER_FOR_ALL"]},"position":5},{"id":"v5-lgg103-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"SCIENTIFIC_GRAPH_NARRATION","statement":"Uma narração diz que “o índice subiu”, enquanto um gráfico mostra aumento até junho e queda em julho. Qual leitura integra os modos?","options":["A narração prova aumento contínuo em todos os meses.","A queda de julho torna o gráfico inutilizável.","O gráfico e a frase entram em tensão quanto ao período; é preciso especificar a tendência e conferir escala.","O som informa a causa da variação."],"correctAnswer":"O gráfico e a frase entram em tensão quanto ao período; é preciso especificar a tendência e conferir escala.","explanation":"A afirmação verbal pode resumir parte da série, mas o gráfico mostra variação temporal; período, escala e medida precisam ser explicitados.","hint":"Compare o intervalo descrito na fala com todos os pontos mostrados.","errorFocus":"Generalizar uma parte da série para todo o período","misconceptions":{"A narração prova aumento contínuo em todos os meses.":["NARRATION_OVERRIDES_DATA"],"A queda de julho torna o gráfico inutilizável.":["LOCAL_REVERSAL_AS_INVALIDITY"],"O som informa a causa da variação.":["AUDIO_AS_CAUSAL_DATA"]},"position":6},{"id":"v5-lgg103-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"RECIPE_ICON_SEQUENCE","statement":"Uma receita ilustrada usa ícones de panela, relógio e seta entre etapas. Qual avaliação do recurso é mais completa?","options":["Os ícones garantem o resultado culinário.","A seta informa sozinha a duração de cada etapa.","Imagens tornam desnecessário considerar instruções verbais.","Ícones e setas podem apoiar a sequência, mas condições como temperatura e duração precisam estar claras no texto ou em outros sinais."],"correctAnswer":"Ícones e setas podem apoiar a sequência, mas condições como temperatura e duração precisam estar claras no texto ou em outros sinais.","explanation":"Ícones e organização espacial ajudam a orientar ações, mas não comunicam automaticamente todas as condições necessárias.","hint":"Identifique o que a sequência visual explica e o que exige especificação adicional.","errorFocus":"Supor que o modo visual comunica toda condição operacional","misconceptions":{"Os ícones garantem o resultado culinário.":["ICON_AS_OUTCOME_GUARANTEE"],"A seta informa sozinha a duração de cada etapa.":["ARROW_AS_TIME"],"Imagens tornam desnecessário considerar instruções verbais.":["VISUAL_AS_COMPLETE_INSTRUCTION"]},"position":7},{"id":"v5-lgg103-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"JUSTIFY","contextFamily":"ALTERNATIVE_POSTER_READINGS","statement":"Em um cartaz, uma porta aberta aparece ao lado de “novas possibilidades”. Uma pessoa lê acolhimento; outra, mudança incerta. Como comparar as leituras?","options":["Verificar quais elementos e contextos sustentam cada leitura, sem supor um sentido universal.","Escolher a interpretação mais popular sem examinar o cartaz.","Afirmar que uma das pessoas não entendeu nada.","Concluir que a imagem determina sozinha a intenção do autor."],"correctAnswer":"Verificar quais elementos e contextos sustentam cada leitura, sem supor um sentido universal.","explanation":"Leituras podem divergir; evidências do texto e contexto permitem compará-las sem transformar uma em verdade automática.","hint":"Peça a cada leitura que aponte uma pista específica e um contexto relevante.","errorFocus":"Resolver divergência interpretativa por votação ou intenção presumida","misconceptions":{"Escolher a interpretação mais popular sem examinar o cartaz.":["POPULARITY_AS_EVIDENCE"],"Afirmar que uma das pessoas não entendeu nada.":["ALTERNATIVE_AS_ERROR"],"Concluir que a imagem determina sozinha a intenção do autor.":["IMAGE_AS_AUTHOR_INTENTION"]},"position":1},{"id":"v5-lgg103-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ADVERTISEMENT_FINE_PRINT","statement":"Um anúncio coloca “grátis” em destaque e apresenta condições de pagamento em texto menor. Qual afirmação é mais bem sustentada?","options":["O anúncio prova que o produto não tem custo em nenhuma circunstância.","A hierarquia pode dar mais destaque à gratuidade enquanto as condições exigem leitura atenta.","O texto menor não faz parte da mensagem.","A composição prova intenção fraudulenta."],"correctAnswer":"A hierarquia pode dar mais destaque à gratuidade enquanto as condições exigem leitura atenta.","explanation":"A hierarquia é observável e pode influenciar a saliência; fraude ou custo efetivo exigem análise das condições e de outras evidências.","hint":"Descreva a hierarquia sem concluir intenção jurídica ou resultado não demonstrado.","errorFocus":"Confundir destaque desigual com prova automática de fraude","misconceptions":{"O anúncio prova que o produto não tem custo em nenhuma circunstância.":["HEADLINE_AS_FULL_TERMS"],"O texto menor não faz parte da mensagem.":["LOW_SALIENCE_AS_EXCLUSION"],"A composição prova intenção fraudulenta.":["DESIGN_AS_INTENT_PROOF"]},"position":2},{"id":"v5-lgg103-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"MUSIC_AND_SCENE","statement":"Uma cena mostra uma comemoração, mas a música é lenta e em tom menor. O que se pode dizer sem fixar a resposta emocional?","options":["A música prova que a cena é triste para todas as pessoas.","A imagem deixa de representar comemoração.","A combinação pode criar ambiguidade ou contraste; outras pistas e o contexto orientam a leitura.","A trilha revela o que cada personagem pensa."],"correctAnswer":"A combinação pode criar ambiguidade ou contraste; outras pistas e o contexto orientam a leitura.","explanation":"A articulação entre imagem e música pode tensionar a cena, mas não determina uma resposta única nem revela estados mentais.","hint":"Considere o contraste e formule mais de uma leitura possível com base em pistas.","errorFocus":"Tratar convenção sonora como significado universal ou acesso à mente","misconceptions":{"A música prova que a cena é triste para todas as pessoas.":["MUSIC_EMOTION_UNIVERSAL"],"A imagem deixa de representar comemoração.":["MODE_CONTRAST_ERASES_IMAGE"],"A trilha revela o que cada personagem pensa.":["SOUND_AS_MIND_READING"]},"position":3},{"id":"v5-lgg103-lock-04","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"BEFORE_AFTER_CAMPAIGN","statement":"Uma campanha exibe fotos de uma praça antes e depois de uma reforma e afirma “a comunidade voltou a se encontrar”. Que evidência seria necessária para sustentar a afirmação sobre encontros?","options":["A diferença de cor entre as fotografias.","O tamanho do logotipo da campanha.","A opinião de quem desenhou o cartaz, sem outros dados.","Observações ou dados de uso da praça, com período e método descritos."],"correctAnswer":"Observações ou dados de uso da praça, com período e método descritos.","explanation":"As imagens podem mostrar alterações físicas; afirmar mudança de encontros requer evidência sobre uso social, com método e contexto.","hint":"Pergunte qual fenômeno a campanha afirma que mudou e que dado o mede diretamente.","errorFocus":"Usar imagens da estrutura física como medida de interação social","misconceptions":{"A diferença de cor entre as fotografias.":["VISUAL_CHANGE_AS_SOCIAL_OUTCOME"],"O tamanho do logotipo da campanha.":["BRANDING_AS_EVIDENCE"],"A opinião de quem desenhou o cartaz, sem outros dados.":["AUTHOR_OPINION_AS_MEASUREMENT"]},"position":4},{"id":"v5-lgg103-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"MULTIMODAL_CLAIM_LIMIT","statement":"Um vídeo combina depoimento, gráficos e música e conclui “o projeto resolveu o problema”. Qual pergunta crítica é mais útil?","options":["Que dados e critérios mostram o que significa “resolver”, e como o gráfico se relaciona ao depoimento?","Qual modo deve ser ignorado para escolher um vencedor?","Que música torna a conclusão mais convincente?","Quantos recursos diferentes aparecem no vídeo?"],"correctAnswer":"Que dados e critérios mostram o que significa “resolver”, e como o gráfico se relaciona ao depoimento?","explanation":"A análise deve relacionar os modos e verificar se evidências e critérios sustentam a afirmação ampla de resultado.","hint":"Investigue o sentido da conclusão e o apoio oferecido por cada modo.","errorFocus":"Confundir força persuasiva com evidência suficiente","misconceptions":{"Qual modo deve ser ignorado para escolher um vencedor?":["MODES_AS_COMPETITORS"],"Que música torna a conclusão mais convincente?":["PERSUASION_AS_PROOF"],"Quantos recursos diferentes aparecem no vídeo?":["COUNTING_MODES_AS_ANALYSIS"]},"position":5},{"id":"v5-lgg103-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"SPATIAL_AFFORDANCE","statement":"Uma planta baixa mostra onde mesas e portas ficam em uma sala. Qual contribuição visual é mais direta nesse caso?","options":["Provar que todas as pessoas circularão sem dificuldade.","Representar relações espaciais entre elementos.","Informar a conversa que ocorrerá na sala.","Demonstrar que a planta foi aprovada por todos."],"correctAnswer":"Representar relações espaciais entre elementos.","explanation":"A disposição espacial é representada diretamente; circulação real depende de dimensões, condições e necessidades das pessoas.","hint":"Identifique que tipo de relação a planta permite observar.","errorFocus":"Confundir representação espacial com experiência real garantida","misconceptions":{"Provar que todas as pessoas circularão sem dificuldade.":["PLAN_AS_UNIVERSAL_ACCESS"],"Informar a conversa que ocorrerá na sala.":["LAYOUT_AS_SPEECH_CONTENT"],"Demonstrar que a planta foi aprovada por todos.":["DIAGRAM_AS_CONSENSUS"]},"position":1},{"id":"v5-lgg103-review-02","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"SEQUENCE_INSTRUCTIONS","statement":"Em uma orientação, a frase “primeiro desligue o aparelho” aparece antes de “retire o cabo”. Que função da linguagem verbal está mais evidente?","options":["Representar uma relação espacial sem ordem.","Comprovar que o cabo foi retirado.","Organizar ações em sequência temporal.","Indicar a reação emocional do leitor."],"correctAnswer":"Organizar ações em sequência temporal.","explanation":"Conectivos e ordenação verbal podem marcar sequência; a instrução não prova que a ação aconteceu.","hint":"Observe as palavras que ordenam as ações.","errorFocus":"Confundir instrução verbal com execução comprovada","misconceptions":{"Representar uma relação espacial sem ordem.":["SEQUENCE_AS_LAYOUT"],"Comprovar que o cabo foi retirado.":["INSTRUCTION_AS_ACTION_RECORD"],"Indicar a reação emocional do leitor.":["PROCEDURAL_TEXT_AS_AFFECT"]},"position":2},{"id":"v5-lgg103-review-03","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"GESTURE_TURN","statement":"Em uma conversa filmada, uma pessoa levanta a mão enquanto outra termina de falar. O que é observável sem interpretar além dos dados?","options":["A pessoa certamente está irritada.","O gesto significa interrupção em toda cultura.","O vídeo mostra o motivo interno do gesto.","O gesto pode marcar intenção de tomar a vez, a ser interpretada com fala e contexto."],"correctAnswer":"O gesto pode marcar intenção de tomar a vez, a ser interpretada com fala e contexto.","explanation":"Gesto e momento oferecem pistas; intenção precisa ser interpretada considerando interação e contexto, não como certeza universal.","hint":"Use o gesto como evidência e evite declarar um estado interno como fato.","errorFocus":"Tratar gesto como código universal e intenção certa","misconceptions":{"A pessoa certamente está irritada.":["GESTURE_AS_EMOTION_CERTAINTY"],"O gesto significa interrupção em toda cultura.":["GESTURE_UNIVERSAL"],"O vídeo mostra o motivo interno do gesto.":["VIDEO_AS_MIND_ACCESS"]},"position":3},{"id":"v5-lgg103-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"COLOR_KEY","statement":"Uma tabela usa círculos azuis para “concluído” e círculos vazios para “pendente”, explicados em uma chave. O que ocorre quando a chave é removida?","options":["A relação entre símbolo e categoria pode ficar menos clara.","Os círculos passam a provar o estado real das tarefas.","A tabela deixa de ser um texto visual.","A cor azul passa a ter significado universal."],"correctAnswer":"A relação entre símbolo e categoria pode ficar menos clara.","explanation":"A chave informa a convenção usada; sem ela, a leitura dos símbolos depende de outras pistas ou conhecimento compartilhado.","hint":"Pense em como o leitor sabe o que cada marca representa.","errorFocus":"Supor convenção gráfica universal sem legenda","misconceptions":{"Os círculos passam a provar o estado real das tarefas.":["SYMBOL_AS_REALTIME_PROOF"],"A tabela deixa de ser um texto visual.":["KEY_REMOVAL_AS_MODE_REMOVAL"],"A cor azul passa a ter significado universal.":["COLOR_CODE_UNIVERSAL"]},"position":4},{"id":"v5-lgg103-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"PHOTO_CROP","statement":"Uma notícia usa uma fotografia muito recortada de uma manifestação e não informa o que ficou fora da moldura. Qual aspecto merece atenção?","options":["O recorte prova intenção de enganar.","O recorte pode limitar o contexto visível; a imagem completa e a legenda ajudam a avaliar a cena.","A fotografia sem moldura mostra todos os participantes.","A legenda nunca influencia a leitura de uma foto."],"correctAnswer":"O recorte pode limitar o contexto visível; a imagem completa e a legenda ajudam a avaliar a cena.","explanation":"Enquadramento seleciona o que aparece; avaliar a cena exige contexto e, quando possível, fonte e imagem mais amplas.","hint":"Pergunte o que o enquadramento mostra e o que ele deixa fora.","errorFocus":"Confundir seleção visual com prova automática de intenção","misconceptions":{"O recorte prova intenção de enganar.":["CROP_AS_INTENT_PROOF"],"A fotografia sem moldura mostra todos os participantes.":["PHOTO_AS_COMPLETE_SCENE"],"A legenda nunca influencia a leitura de uma foto.":["IMAGE_INDEPENDENT_OF_CAPTION"]},"position":5},{"id":"v5-lgg103-review-06","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"JUSTIFY","contextFamily":"DATA_SOURCE_LABEL","statement":"Um gráfico mostra “45%” em destaque; a fonte e o número de respostas aparecem em nota pequena. Que leitura é mais responsável?","options":["O percentual basta para provar uma tendência geral.","A fonte pequena deve ser ignorada porque está fora do gráfico.","A nota pode informar origem e tamanho da amostra; ambos são relevantes para interpretar o percentual.","O destaque visual prova que a amostra é aleatória."],"correctAnswer":"A nota pode informar origem e tamanho da amostra; ambos são relevantes para interpretar o percentual.","explanation":"Fonte e base de cálculo ajudam a avaliar alcance e limites de um percentual; saliência não valida amostragem.","hint":"Observe quais informações permitem interpretar de onde vem o número e a quem ele se refere.","errorFocus":"Interpretar percentual sem fonte ou denominador","misconceptions":{"O percentual basta para provar uma tendência geral.":["PERCENT_AS_GENERALIZATION"],"A fonte pequena deve ser ignorada porque está fora do gráfico.":["SMALL_PRINT_AS_IRRELEVANT"],"O destaque visual prova que a amostra é aleatória.":["VISUAL_PROMINENCE_AS_METHOD"]},"position":6},{"id":"v5-lgg103-review-07","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"SILENT_FILM_TEXT","statement":"Um vídeo sem fala mostra uma porta se fechando e, em seguida, aparece a frase “fim do expediente”. Como os modos colaboram?","options":["A frase prova por que a porta foi fechada.","O vídeo não comunica nada por não ter fala.","A imagem informa o horário exato do expediente.","A frase pode ancorar uma leitura temporal da cena, sem explicar todos os detalhes visuais."],"correctAnswer":"A frase pode ancorar uma leitura temporal da cena, sem explicar todos os detalhes visuais.","explanation":"O texto verbal direciona a leitura da ação, enquanto a imagem fornece outros detalhes; causa e horário exato não estão demonstrados.","hint":"Separe o que a frase acrescenta do que a imagem mostra por si.","errorFocus":"Tratar uma legenda curta como explicação completa ou causal","misconceptions":{"A frase prova por que a porta foi fechada.":["CAPTION_AS_CAUSE"],"O vídeo não comunica nada por não ter fala.":["SPEECH_AS_ONLY_MODE"],"A imagem informa o horário exato do expediente.":["SCENE_AS_CLOCK"]},"position":7},{"id":"v5-lgg103-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ICON_TRANSLATION","statement":"Um aplicativo substitui o ícone de envelope por um ícone de sino em um botão de notificações. O que precisa ser testado antes de concluir que a mudança melhorou a compreensão?","options":["Como usuários do público previsto interpretam e usam o botão em tarefas relevantes.","A preferência de quem desenhou os ícones.","A cor do botão em uma captura isolada.","O número de pixels do ícone, sem observar seu uso."],"correctAnswer":"Como usuários do público previsto interpretam e usam o botão em tarefas relevantes.","explanation":"A função comunicativa pretendida não prova compreensão; observação com usuários e tarefas contextualizadas fornece evidência mais direta.","hint":"Qual dado mede a compreensão e o uso, em vez da intenção de projeto?","errorFocus":"Confundir intenção de design com compreensão demonstrada","misconceptions":{"A preferência de quem desenhou os ícones.":["DESIGNER_PREFERENCE_AS_USER_EVIDENCE"],"A cor do botão em uma captura isolada.":["APPEARANCE_AS_USABILITY_TEST"],"O número de pixels do ícone, sem observar seu uso.":["SIZE_AS_COMPREHENSION"]},"position":8},{"id":"v5-lgg103-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"AUDIENCE_EFFECT_CLAIM","statement":"Uma equipe afirma que “a trilha sonora faz qualquer estudante prestar atenção”. Qual reformulação distingue análise do texto e evidência de recepção?","options":["A trilha garante atenção porque foi escolhida pela equipe.","A trilha pode destacar transições; para afirmar atenção do público, seria necessário observar ou medir a recepção.","A música não pode contribuir para o sentido de um vídeo.","Todos os sons produzem a mesma resposta em qualquer pessoa."],"correctAnswer":"A trilha pode destacar transições; para afirmar atenção do público, seria necessário observar ou medir a recepção.","explanation":"É possível analisar a função sonora na composição; alegações sobre atenção exigem dados de recepção e não devem ser universalizadas.","hint":"Separe a escolha sonora observável do comportamento atribuído à audiência.","errorFocus":"Afirmar efeito cognitivo universal sem dados de recepção","misconceptions":{"A trilha garante atenção porque foi escolhida pela equipe.":["AUTHOR_INTENT_AS_AUDIENCE_EFFECT"],"A música não pode contribuir para o sentido de um vídeo.":["SOUND_AS_DECORATION_ONLY"],"Todos os sons produzem a mesma resposta em qualquer pessoa.":["UNIVERSAL_COGNITIVE_EFFECT"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-languages-semiotic-function',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-languages-semiotic-function' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'LANGUAGES', 'LINGUAGENS_MULTISSEMIOTICAS', 'relacao entre recursos semióticos e producao de sentidos',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
